import re, subprocess, json
from pathlib import Path
root=Path('e:/PVE')
passive_path=root/'game/dzsj/scripts/npc/item stats/shop1_items_enhance_passive.txt'
text=passive_path.read_text(encoding='utf-8', errors='ignore')

# parse passive file
entries = {}
current=None
for line in text.splitlines():
    m = re.match(r'\t"([^"]+)"\s*$', line)
    if m:
        current = m.group(1)
        entries[current] = []
        continue
    if current:
        fm = re.match(r'\t\t"([^"]+)"\s+"([^"]*)"', line)
        if fm:
            entries[current].append(fm.group(1))

# function to find lua files referencing ability name
vscripts = root/'game/dzsj/scripts/vscripts'

report = {}
for name, fields in entries.items():
    try:
        proc = subprocess.run(['rg','-l',name,str(vscripts)], capture_output=True, text=True)
        files = [f for f in proc.stdout.splitlines() if f.strip()]
    except FileNotFoundError:
        files = []
    # gather GetSpecialValueFor usage in those files
    get_fields=set()
    self_usage = {}
    for f in files:
        content = Path(f).read_text(encoding='utf-8', errors='ignore')
        for m in re.finditer(r'GetSpecialValueFor\("([^"]+)"\)', content):
            get_fields.add(m.group(1))
        # count self.<field> usage
        for field in fields:
            # count occurrences of self.<field>
            cnt = len(re.findall(r'\bself\.%s\b' % re.escape(field), content))
            if cnt:
                self_usage[field] = self_usage.get(field, 0) + cnt
    report[name] = {
        'fields': fields,
        'files': files,
        'get_fields': sorted(get_fields),
        'self_usage': self_usage,
    }

# compute unused fields by heuristic
summary = {}
for name, info in report.items():
    fields = info['fields']
    get_fields = set(info['get_fields'])
    unused = []
    dead_read = []
    for field in fields:
        if field not in get_fields:
            unused.append(field)
        else:
            # if stored to self and only used once (assignment), consider dead_read
            if info['self_usage'].get(field,0) == 1:
                # check if assignment exists in files
                dead_read.append(field)
    summary[name] = {
        'unused': unused,
        'dead_read': dead_read,
        'files': info['files'],
        'get_fields': info['get_fields'],
    }

(Path('e:/PVE/.tmp')).mkdir(exist_ok=True)
(Path('e:/PVE/.tmp/shop1_passive_usage_fields.json')).write_text(json.dumps(summary, indent=2), encoding='utf-8')
print('entries', len(entries))
# show any unused or dead_read fields
for name, info in summary.items():
    if info['unused'] or info['dead_read']:
        print(name, 'unused', info['unused'], 'dead_read', info['dead_read'])
'@ | python -
"}

